head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > M > setText]<br/>구분자로 구분한 아이템의 라벨값을 사용하여 아이템들을 선택합니다.<br/>기존 선택은 모두 해제되고 새롭게 아이템들이 선택 처리됩니다.",
    "validation" : [
        "label(필수) 파라미터로 선택하려는 아이템들의 라벨값을 separator 속성값의 구분자로 구분한 문자열로 설정합니다.",
        "label(필수) 파라미터로 설정한 아이템들이 모두 선택됩니다. (singleSelect 속성에 관계없이 모두 선택)",
        "기존에 선택된 아이템은 모두 해제되고 새롭게 아이템들이 선택 처리됩니다.",
        "라벨값은 대소문자를 구분하며 아이템의 라벨값과 정확히 일치해야 합니다.",
        "label(필수) 파라미터에 빈 문자열('')을 설정하면 모든 아이템이 선택 해제됩니다.",
        "아이템의 선택이 변경되면 onchange 이벤트가 발생합니다.",
        "ref 속성으로 DataCollection 과 바인딩된 경우 바인딩된 데이터에도 변경된 값이 반영됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출 (gdl_multiselect, gdl_boolean 포함)
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// onchange 이벤트 핸들러 — multiselect onchange 는 파라미터 없음 (engine spec)
// 변경된 값은 getValue() / getSelectedIndex() 메소드로 직접 조회
scwin.target1_onchange = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange=====");
    wf_body_bottom.getObj("scwin").setReturnValue("getValue() : [" + target1.getValue() + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("getSelectedIndex() : [" + target1.getSelectedIndex() + "]");
};



// comp 생성 (createBasicMultiSelect 로 동적 생성, separator/singleSelect/ref 적용 + onchange 핸들러)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // gdl_multiselect 재생성 (idempotent: 기존 dataList 제거 후 재생성)
    $c.gcm.createDataListMultiSelect();

    // dlt_ref 초기화 (ref 바인딩 검증용)
    dlt_ref.set(0, "value", "");

    // 옵션 값 수집
    let cSeparator = con_separator.getText();
    let cSingleSelect = con_singleSelect.getText();
    let cRef = con_ref.getText();

    let properties = {};
    if (cSeparator !== "") {
        properties.separator = cSeparator;
    }
    if (cSingleSelect !== "") {
        properties.singleSelect = cSingleSelect;
    }
    if (cRef === "true") {
        properties.ref = "data:dlt_ref.value";
    }
    let cList = $c.gcm.createCList(properties);

    // 현재 적용된 옵션 정보 라벨 표시
    let lblTxt = 'target1 : ';
    lblTxt += 'separator=[' + (cSeparator === "" ? "미설정(기본 공백)" : cSeparator) + '], ';
    lblTxt += 'singleSelect=[' + (cSingleSelect === "" ? "미설정(기본 false)" : cSingleSelect) + '], ';
    lblTxt += 'ref=[' + (cRef === "true" ? "data:dlt_ref.value" : "미설정") + ']';
    $c.gcm.createLabel('label="' + lblTxt + '"', '', 'label1');

    // onchange 핸들러 부착 (createBasicMultiSelect 의 두번째 인자 eHandler)
    let eHandler = 'ev:onchange="scwin.target1_onchange"';

    // comp 생성 함수 호출
    await $c.gcm.createBasicMultiSelect(cList, eHandler);
}



// setText(label) - label 인자(separator 구분 라벨 문자열)로 다중 선택
//   예: separator="," + par_label="multiselect1,multiselect3" → multiselect1, multiselect3 선택
scwin.btn_setText_onclick = function (e) {
    let inputVal = par_label.getValue();
    target1.setText(inputVal);
    wf_body_bottom.getObj("scwin").setReturnValue("target1.setText('" + inputVal + "') 호출");
    wf_body_bottom.getObj("scwin").setReturnValue("getText() : [" + target1.getText() + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("getValue() : [" + target1.getValue() + "]");
};



// setText("") - 빈 문자열 설정 시 모든 아이템 선택 해제
scwin.btn_setTextEmpty_onclick = function (e) {
    target1.setText("");
    wf_body_bottom.getObj("scwin").setReturnValue("target1.setText('') 호출 - 모든 선택 해제");
    wf_body_bottom.getObj("scwin").setReturnValue("getText() : [" + target1.getText() + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("getValue() : [" + target1.getValue() + "]");
};



// 사전 선택 - 기존 선택 해제 검증용 (인덱스 0 만 미리 선택)
scwin.btn_preselect_onclick = function (e) {
    target1.setValue("");
    target1.setSelectedIndexNM(0, true);
    target1.setInstanceValue();
    wf_body_bottom.getObj("scwin").setReturnValue("target1 : 사전 선택 (인덱스 0) 완료");
    wf_body_bottom.getObj("scwin").setReturnValue("getText() : [" + target1.getText() + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("getValue() : [" + target1.getValue() + "]");
};



// 결과 확인 - getText / getValue 호출 결과 출력
scwin.btn_getResult_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("getText() : [" + target1.getText() + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("getValue() : [" + target1.getValue() + "]");
};



// dlt_ref 값 확인 - ref 바인딩 시 setText 호출 결과 반영 검증용
scwin.btn_getDataList_onclick = function (e) {
    let v = dlt_ref.get(0, "value");
    wf_body_bottom.getObj("scwin").setReturnValue("dlt_ref row 0 value : [" + v + "]");
};
